#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-08-31
#
# Tests for the #3835 vehicle: write-operator-permissions.mjs (the consent-gated
# operator-scope writer) and doctor's check-operator-permissions.sh. Fails on
# main, where neither file exists: the control for the whole PR.
set -euo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT="$(cd "$HERE/../.." && pwd)"
WRITER="$ROOT/src/skills/setup/scripts/write-operator-permissions.mjs"
CHECKER="$ROOT/src/skills/doctor/scripts/check-operator-permissions.sh"
PAYLOAD="$ROOT/src/skills/setup/references/operator-permissions.json"

PASS=0; FAIL=0
ok()  { PASS=$((PASS+1)); echo "  ok: $1"; }
bad() { FAIL=$((FAIL+1)); echo "  FAIL: $1"; }

T="$(mktemp -d "${TMPDIR:-/tmp}/op-perm-test.XXXXXX")"
trap 'rm -rf "$T"' EXIT

[ -f "$WRITER" ] && ok "writer exists" || bad "writer missing"
[ -f "$CHECKER" ] && ok "checker exists" || bad "checker missing"
[ -f "$PAYLOAD" ] && ok "payload exists" || bad "payload missing"
[ "$FAIL" -eq 0 ] || { echo "Results: $PASS passed, $FAIL failed"; exit 1; }

N_PAYLOAD="$(node -e 'console.log(JSON.parse(require("fs").readFileSync(process.argv[1],"utf8")).deny.length)' "$PAYLOAD")"
[ "$N_PAYLOAD" -ge 30 ] && ok "payload carries $N_PAYLOAD deny rules" || bad "payload too small: $N_PAYLOAD"

S="$T/settings.json"

# 1. dry run writes nothing
node "$WRITER" --settings-path "$S" --dry-run --json > "$T/dry.json"
[ ! -e "$S" ] && ok "dry run creates no file" || bad "dry run wrote the target"
grep -q '"applied": false' "$T/dry.json" && ok "dry run reports applied:false" || bad "dry run applied flag wrong"

# 2. apply to a missing file creates it with the full payload
node "$WRITER" --settings-path "$S" --json > "$T/apply1.json"
N_WRITTEN="$(node -e 'console.log(JSON.parse(require("fs").readFileSync(process.argv[1],"utf8")).permissions.deny.length)' "$S")"
[ "$N_WRITTEN" -eq "$N_PAYLOAD" ] && ok "fresh apply writes all $N_PAYLOAD rules" || bad "fresh apply wrote $N_WRITTEN"

# 3. idempotent: second apply adds nothing
node "$WRITER" --settings-path "$S" --json > "$T/apply2.json"
grep -q '"additions": \[\]' "$T/apply2.json" && ok "second apply is a no-op" || bad "second apply added rules"

# 4. union preserves user content and their own rules
node -e '
const fs=require("fs");
fs.writeFileSync(process.argv[1], JSON.stringify({model:"opus", permissions:{deny:["Bash(shutdown *)"], allow:["Read"]}}, null, 2));' "$T/user.json"
node "$WRITER" --settings-path "$T/user.json" --json > "$T/apply3.json"
node -e '
const s=JSON.parse(require("fs").readFileSync(process.argv[1],"utf8"));
const ok = s.model==="opus" && s.permissions.allow[0]==="Read" && s.permissions.deny[0]==="Bash(shutdown *)";
process.exit(ok?0:1)' "$T/user.json" && ok "user keys, allow list and own deny order preserved" || bad "merge clobbered user content"

# 5. backup exists and rollback restores byte-identical content
BACKUP_COUNT="$(ls "$T"/user.json.ork-backup-* 2>/dev/null | wc -l | tr -d ' ')"
[ "$BACKUP_COUNT" -ge 1 ] && ok "backup created" || bad "no backup"
cp "$T/user.json" "$T/after-apply.json"
node "$WRITER" --settings-path "$T/user.json" --rollback > /dev/null
node -e '
const f=require("fs");
const rolled=JSON.parse(f.readFileSync(process.argv[1],"utf8"));
process.exit(Array.isArray(rolled.permissions.deny) && rolled.permissions.deny.length===1 ? 0 : 1)' "$T/user.json" \
  && ok "rollback restored the pre-apply file" || bad "rollback did not restore"

# 6. unparseable target: exit 2, untouched
printf '{broken' > "$T/broken.json"
RC=0; node "$WRITER" --settings-path "$T/broken.json" > /dev/null 2>&1 || RC=$?
[ "$RC" -eq 2 ] && ok "unparseable target exits 2" || bad "unparseable target rc=$RC"
[ "$(cat "$T/broken.json")" = "{broken" ] && ok "unparseable target untouched" || bad "unparseable target modified"

# 7. checker: red on empty scopes, green after apply, sandbox reported
H="$T/home-red"; mkdir -p "$H/.claude"
RC=0; ORK_SETTINGS_HOME="$H" bash "$CHECKER" "$T/no-such-project" --json > "$T/check-red.json" || RC=$?
[ "$RC" -eq 1 ] && ok "checker exits 1 with no rules anywhere" || bad "checker red rc=$RC"
grep -q '"remedy":' "$T/check-red.json" && ok "checker names the remedy" || bad "no remedy in checker output"

node "$WRITER" --settings-path "$H/.claude/settings.json" --json > /dev/null
RC=0; ORK_SETTINGS_HOME="$H" bash "$CHECKER" "$T/no-such-project" --json > "$T/check-green.json" || RC=$?
[ "$RC" -eq 0 ] && ok "checker exits 0 after the writer ran" || bad "checker green rc=$RC"

# 8. sandbox posture surfaces
node -e '
const f=require("fs"); const p=process.argv[1];
const s=JSON.parse(f.readFileSync(p,"utf8"));
s.sandbox={enabled:true,network:{allowedDomains:["github.com"]}};
f.writeFileSync(p, JSON.stringify(s,null,2));' "$H/.claude/settings.json"
ORK_SETTINGS_HOME="$H" bash "$CHECKER" "$T/no-such-project" --json > "$T/check-sb.json" || true  # silent: known-noise
grep -q '"network": "allowlist"' "$T/check-sb.json" && ok "sandbox allowlist posture reported" || bad "sandbox posture missing"

# 9. #3877: a project-scope sandbox.enabled:false over a user scope that sets it true
#    is reported with the project file:line and the user file:line, never failed on.
H2="$T/home-sb"; mkdir -p "$H2/.claude"
printf '{\n  "sandbox": {\n    "enabled": true\n  }\n}\n' > "$H2/.claude/settings.json"
PJ="$T/proj-override"; mkdir -p "$PJ/.claude"
printf '{\n  "permissions": {},\n  "sandbox": {\n    "enabled": false\n  }\n}\n' > "$PJ/.claude/settings.local.json"
ORK_SETTINGS_HOME="$H2" bash "$CHECKER" "$PJ" --json > "$T/check-ov.json" || true  # exit 1 expected: H2 carries no deny payload
node -e '
const o=JSON.parse(require("fs").readFileSync(process.argv[1],"utf8")); const ov=o.sandbox_override;
const ok = ov && ov.file===process.argv[2] && ov.line===4 && ov.user_file===process.argv[3] && ov.user_line===3
  && o.sandbox.enabled==="false" && o.sandbox.source===process.argv[2];
process.exit(ok?0:1)' "$T/check-ov.json" "$PJ/.claude/settings.local.json" "$H2/.claude/settings.json" \
  && ok "sandbox override names the project file:line and the user file:line" || bad "sandbox override missing or wrong: $(head -c 600 "$T/check-ov.json")"
ORK_SETTINGS_HOME="$H2" bash "$CHECKER" "$PJ" > "$T/check-ov.txt" || true
grep -q 'warn: sandbox override: .*settings.local.json:4 sets sandbox.enabled=false' "$T/check-ov.txt" && ok "text mode prints the override warning" || bad "text mode has no override warning"

# 9b. control: no project settings at all, user scope true: no override
ORK_SETTINGS_HOME="$H2" bash "$CHECKER" "$T/no-such-project" --json > "$T/check-noov.json" || true
grep -q '"sandbox_override": null' "$T/check-noov.json" && ok "no project settings: sandbox_override null" || bad "false positive override with no project settings"

# 9c. control: project false but user scope unset: nothing is overridden
H3="$T/home-unset"; mkdir -p "$H3/.claude"; printf '{}\n' > "$H3/.claude/settings.json"
ORK_SETTINGS_HOME="$H3" bash "$CHECKER" "$PJ" --json > "$T/check-unset.json" || true
grep -q '"sandbox_override": null' "$T/check-unset.json" && ok "project false with user unset: no override reported" || bad "override reported with nothing to override"

# 9d. control: project true over user true: no override
PJ2="$T/proj-true"; mkdir -p "$PJ2/.claude"; printf '{\n  "sandbox": {\n    "enabled": true\n  }\n}\n' > "$PJ2/.claude/settings.json"
ORK_SETTINGS_HOME="$H2" bash "$CHECKER" "$PJ2" --json > "$T/check-both.json" || true
grep -q '"sandbox_override": null' "$T/check-both.json" && ok "project true over user true: no override" || bad "override reported when both scopes agree"

echo "Results: $PASS passed, $FAIL failed"
[ "$FAIL" -eq 0 ]
